def batch_ms(b, t0, t1):
    return t0 + b * t1


def best_batch(t0, t1, slo):
    if slo < t0 + t1:
        return 0
    return int((slo - t0) // t1)


def throughput(b, t0, t1):
    return b / batch_ms(b, t0, t1) * 1000


for slo in (50, 20):
    b = best_batch(8, 0.5, slo)
    print(slo, 'ms ->', b, 'requests,', round(throughput(b, 8, 0.5)), 'req/s')
